command:
D=$(mktemp -d /tmp/persona-dream-dynamic-reply.XXXXXX)
cat > "$D/journal_entry.json" <<'JSON'
{"journal":"I watched the glass mask tilt toward Graham after the deadline slipped.","unresolved_tension":"help without false certainty","expanded_understanding":"care can admit what it does not know","session_mood":{"mood_label":"memory_uncertain","mood_description":"careful, present, unsure"}}
JSON
cat > "$D/dialogue_authoring.json" <<'JSON'
{
  "schema": "persona_dream.dialogue_authoring_receipt.v1",
  "turn_binding": {"asked_sha256": "sha256:stale", "prompt_sha256": "sha256:stale", "conversation_sha256": "sha256:stale"},
  "provider_packet": {"summary": "stale pre-generated authoring receipt that dynamic conversation must ignore"},
  "webgpt": {"handler": "webgpt", "status": "PASS", "provider_live": true},
  "webkimi": {"handler": "webkimi", "status": "PASS", "provider_live": true},
  "humanized_draft": {
    "reply": "STALE PREGENERATED PROSE SHOULD NOT BE USED",
    "tone": "memory_uncertain",
    "chatterbox_utterance_text": "[sigh] STALE PREGENERATED PROSE SHOULD NOT BE USED [sniff]"
  }
}
JSON
uv run --project .. python - "$D" <<'PYCODE'
import sys
from pathlib import Path
sys.path.insert(0, '../scripts')
import speak_reply as srep
run=Path(sys.argv[1])
(run/'fake.wav').write_bytes(b'RIFF' + b'0'*12000)
class FakeAdapter:
    @staticmethod
    def dispatch_text_reasoning(prompt, role, output_contract, caller_skill, timeout_s):
        assert role == 'persona_reply'
        assert 'THE CONVERSATION SO FAR' in prompt
        return ({
            'reply': 'The glass mask is the live thing I can answer from now, and I do not want to pretend I know the weight of Graham’s deadline.',
            'tone': 'memory_uncertain',
            'chatterbox_utterance_text': '[sigh] The glass mask is the live thing I can answer from now ... and I do not want to pretend I know the weight of Graham’s deadline. [sniff]'
        }, {'schema':'tau.persona_dream.scillm_text_reasoning_receipt.v1','status':'PASS','model':'fake-dynamic','live_call_performed':False})
    @staticmethod
    def receipt_provenance(receipt):
        return {'route':'tau:persona-dream-text-reasoning','status':receipt.get('status'),'model':receipt.get('model')}
orig_load = srep._load
def fake_load(name):
    if name == 'tau_text_reasoning_adapter':
        return FakeAdapter
    return orig_load(name)
srep._load = fake_load
def fake_speak(text, voice_delivery, run_dir, label):
    return run_dir/'fake.wav', {'engine':'fake-agentic','render_plan':{'chunks':[{'text': text}]}, 'crossfade_ms': 0, 'render_path':'fake'}
srep.speak = fake_speak
result=srep.generate_and_speak(run_dir=run, prompt_text='I am exhausted by the slipped deadline')
assert result['status']=='PASS_REPLY_SPOKEN', result
assert 'STALE PREGENERATED' not in result['text'], result
assert result['tau_receipt']['route']=='tau:persona-dream-text-reasoning', result['tau_receipt']
assert 'dialogue_authoring' not in result, result
assert result['chatterbox_utterance_source']=='model_authored', result['chatterbox_utterance_source']
print('DYNAMIC_CONVERSATION_IGNORES_PREGENERATED_AUTHORING_OK')
PYCODE
